#include "nova64/memory/rdram.hpp"
#include <stdexcept>
namespace nova64 { Rdram::Rdram(uint32_t n):bytes_(n){} uint8_t Rdram::read8(uint32_t a){if(a>=bytes_.size())throw std::out_of_range("RDRAM read");return bytes_[a];} void Rdram::write8(uint32_t a,uint8_t v){if(a>=bytes_.size())throw std::out_of_range("RDRAM write");bytes_[a]=v;} uint16_t Rdram::read16(uint32_t a){return read8(a)<<8|read8(a+1);} uint32_t Rdram::read32(uint32_t a){return uint32_t(read16(a))<<16|read16(a+2);} uint64_t Rdram::read64(uint32_t a){return uint64_t(read32(a))<<32|read32(a+4);} void Rdram::write16(uint32_t a,uint16_t v){write8(a,v>>8);write8(a+1,v);} void Rdram::write32(uint32_t a,uint32_t v){write16(a,v>>16);write16(a+2,v);} void Rdram::write64(uint32_t a,uint64_t v){write32(a,v>>32);write32(a+4,v);} uint32_t Rdram::size()const{return bytes_.size();} }
